86	void name_installed_printers(Plater& plater, const Printers::VendorMap& before)
87	{
88	    PresetBundle&     presets  = *wxGetApp().preset_bundle;
89	    const std::string selected = presets.printers.get_selected_preset_name();
90	    const Preset&     current  = presets.printers.get_selected_preset();
91	    const auto        models   = Printers::newly_installed_models(before, wxGetApp().app_config->vendors(),
92	                                                                  current.config.opt_string("printer_model"),
93	                                                                  current.config.opt_string("printer_variant"));
94	    std::string keep;
95	    for (const Printers::InstalledModel& model : models) {
96	        const Preset* profile = presets.printers.find_system_preset_by_model_and_variant(model.model, model.variant);
97	        if (profile == nullptr)
98	            throw std::runtime_error("The wizard enabled " + model.model + " " + model.variant +
99	                                     " but no system profile for it is loaded");
100	        const std::string profile_name = profile->name;
101	        if (!SetupCommands::select_printer_preset(plater, profile_name) ||
102	            presets.printers.get_selected_preset_name() != profile_name)
103	            return; // the person kept unsaved printer changes; nothing more is named
104	        const std::string name = Printers::add_named_printer(plater, model.model, {});
105	        if (profile_name == selected)
106	            keep = name;
107	    }
108	    // Naming selects each printer in turn; the wizard's own choice is the one
109	    // left selected, under its name when it was one of them.
110	    if (!models.empty())
111	        SetupCommands::select_printer_preset(plater, keep.empty() ? selected : keep);
112	}
