169	{
170	    // A missing token file or profile index is a packaging defect, not a state
171	    // this flow can recover from, so it propagates like it does from the
172	    // printer menu's entry point.
173	    const ShellTheme theme = ShellTheme::load_from_resources();
174	    show_printer_setup(owner, theme, dark, plater);
175	}
